const matchMarkets = [{ kind: 'MATCH', question: 'Will Brazil win against Germany?', price: '64.2c' }, { kind: 'SCORE', question: 'Will the most likely score be 2-1?', price: '14.8c' }, { kind: 'TOTAL', question: 'Will the match have over 2.5 goals?', price: '57.1c' }]
