function setTheme(value) { theme.value = value; window.localStorage?.setItem('socceroctopus-atlas-theme', value) }
onMounted(() => { const saved = window.localStorage?.getItem('socceroctopus-atlas-theme'); theme.value = saved === 'light' || saved === 'dark' ? saved : window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light' })
